function validate([targetX, targetY]) {
  if (!Number.isInteger(targetX) || targetX < 1 || targetX > 1000000000) return 'targetX is an integer from 1 to 10^9.';
  if (!Number.isInteger(targetY) || targetY < 1 || targetY > 1000000000) return 'targetY is an integer from 1 to 10^9.';
  return null;
}

