function isReachable(targetX, targetY) {
  let a = targetX;
  let b = targetY;
  while (b !== 0) {
    const remainder = a % b;
    a = b;
    b = remainder;
  }

  let gcd = a;
  while (gcd % 2 === 0) {
    gcd /= 2;
  }
  return gcd === 1;
}

