function isReachable(targetX, targetY) {
  // Undo moves from the target: halve an even coordinate, or add two different odd ones (making one even).
  let x = targetX, y = targetY;
  while (x !== 1 || y !== 1) {
    if (x % 2 === 0) x /= 2;
    else if (y % 2 === 0) y /= 2;
    else if (x === y) return false;
    else if (x > y) x += y;
    else y += x;
  }
  return true;
}

