function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size !== 'large') return [pick(1, 24), pick(1, 24)];
  const mode = Math.floor(rand() * 3);
  if (mode === 0) return [pick(1, 1000000000), pick(1, 1000000000)];
  const factor = mode === 1 ? 2 ** pick(0, 20) : 2 * pick(1, 500) + 1;
  const cap = Math.floor(1000000000 / factor);
  return [factor * pick(1, cap), factor * pick(1, cap)];
}
